"""Independent check: try to beat the planner's answer with local search."""
import json, random, subprocess, sys

def benefit_of(fid, req):
    f = next(x for x in req['flows'] if x['id']==fid)
    tmpl=bytes.fromhex(f['template']); kinds=f['kinds']; N=len(f['path'])
    per=(len(tmpl)-4-kinds.count('D'))*N
    q=kinds.index('Q'); t=kinds.index('T'); rem=req['warmup']; elig=0
    for run in req['offers'][fid]:
        c=run['count']
        if rem>=c: rem-=c; continue
        fresh=c-rem; rem=0
        hdr=bytes.fromhex(run['header'])
        ok=all(hdr[i]==tmpl[i] for i,ch in enumerate(kinds) if ch=='K')
        if ok and hdr[q]<=7 and hdr[t]>N-1: elig+=fresh
    return per*elig

def feasible(sel, req):
    use={}
    for fid in sel:
        f=next(x for x in req['flows'] if x['id']==fid)
        for n in f['path']: use[n]=use.get(n,0)+1
    return all(c<=req['capacities'][n] for n,c in use.items())

def check(req, got):
    ids=[f['id'] for f in req['flows']]
    bens={i:benefit_of(i,req) for i in ids}
    cur=list(got['selected'])
    assert feasible(cur,req), 'returned set infeasible'
    assert set(req['pinned'])<=set(cur), 'pinned missing'
    best=sum(bens[i] for i in cur)
    if got['saved']!=best: return 'saved mismatch %s vs %s'%(got['saved'],best)
    rng=random.Random(12345)
    for restart in range(60):
        sel=list(cur)
        if restart: sel=rng.sample(ids, rng.randint(0,len(ids)))
        if not feasible(sel,req): continue
        val=sum(bens[i] for i in sel)
        improved=True
        while improved:
            improved=False
            for i in ids:
                if i in sel:
                    trial=[x for x in sel if x!=i]
                    if feasible(trial,req):
                        v=sum(bens[x] for x in trial)
                        if v>val: sel=trial; val=v; improved=True
                else:
                    trial=sel+[i]
                    if feasible(trial,req):
                        v=sum(bens[x] for x in trial)
                        if v>val: sel=trial; val=v; improved=True
        if val>got['saved']:
            return 'better set found: %s > %s'%(val,got['saved'])
    return None

